





SELECT md5('ROAD_' || t.id::text)::uuid, t.from_node_id, t.to_node_id, 'MIXED_ROAD', t.length_km, LEAST(t.base_speed_kmh, 50.0), FALSE, 1.40, FALSE
FROM track_segments t
WHERE t.segment_type = 'TRAM_TRACK'
  AND EXISTS (
      SELECT 1
      FROM routes r
      JOIN route_stops a ON a.route_id = r.id
      JOIN route_stops b ON b.route_id = r.id AND b.stop_sequence_order = a.stop_sequence_order + 1
      WHERE (r.route_type = 'PERMANENT_BUS' OR (r.route_type = 'TEMPORARY_REPLACEMENT' AND length(r.line_number) >= 3))
        AND a.stop_node_id = t.from_node_id
        AND b.stop_node_id = t.to_node_id
  )
  AND NOT EXISTS (
      SELECT 1 FROM track_segments o
      WHERE o.from_node_id = t.from_node_id AND o.to_node_id = t.to_node_id AND o.segment_type <> 'TRAM_TRACK'
  );

SELECT DISTINCT ON (t.from_node_id, t.to_node_id)
       md5('TRACK_' || t.id::text)::uuid, t.from_node_id, t.to_node_id, 'TRAM_TRACK', t.length_km, t.base_speed_kmh, TRUE, 1.05, FALSE
FROM track_segments t
WHERE t.segment_type <> 'TRAM_TRACK'
  AND EXISTS (
      SELECT 1
      FROM routes r
      JOIN route_stops a ON a.route_id = r.id
      JOIN route_stops b ON b.route_id = r.id AND b.stop_sequence_order = a.stop_sequence_order + 1
      WHERE (r.route_type = 'PERMANENT_TRAM' OR (r.route_type = 'TEMPORARY_REPLACEMENT' AND length(r.line_number) < 3))
        AND a.stop_node_id = t.from_node_id
        AND b.stop_node_id = t.to_node_id
  )
  AND NOT EXISTS (
      SELECT 1 FROM track_segments o
      WHERE o.from_node_id = t.from_node_id AND o.to_node_id = t.to_node_id AND o.segment_type = 'TRAM_TRACK'
  )
ORDER BY t.from_node_id, t.to_node_id, t.id;
